// ============================================
// EXTRACT QUERY PARAMS (RFC-003)
// ============================================

const input = $input.first().json;
const query = input.query || {};
const headers = input.headers || {};

// Extract project_id from header or query
const projectId = headers['x-project-id'] 
  || headers['X-Project-ID'] 
  || query.project_id 
  || null;

// Extract guild_id from query
const guildId = query.guild_id || null;

return {
  project_id: projectId,
  guild_id: guildId,
  has_branding_params: !!(projectId)
};

// ============================================
// GENERATE CANCEL HTML PAGE (RFC-003 Branding)
// ============================================

// Try to get branding from API response
let branding = {};
try {
  const apiResponse = $('Get Branding').first().json;
  branding = apiResponse.data || apiResponse.branding || {};
} catch (e) {
  // No branding available, use defaults
}

// Branding data with defaults
const brandName = branding.name || 'Bot Appetit';
const logoUrl = branding.logo_url || '';
const primaryColor = branding.primary_color || '#F59E0B';
const discordUrl = branding.discord_url || 'https://discord.com/channels/@me';

// Logo HTML (only if URL provided)
const logoHtml = logoUrl 
  ? `<img src="${logoUrl}" alt="${brandName}" style="max-width: 120px; max-height: 80px; margin-bottom: 16px;">` 
  : '';

const html = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Paiement annulé - ${brandName}</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 20px;
    }
    .card {
      background: white;
      border-radius: 16px;
      padding: 40px;
      max-width: 400px;
      width: 100%;
      text-align: center;
      box-shadow: 0 20px 60px rgba(0,0,0,0.3);
    }
    .logo {
      margin-bottom: 16px;
    }
    .icon {
      width: 80px;
      height: 80px;
      background: #F59E0B;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 24px;
    }
    .icon svg {
      width: 40px;
      height: 40px;
      fill: white;
    }
    h1 {
      color: #1F2937;
      font-size: 24px;
      margin-bottom: 16px;
    }
    p {
      color: #6B7280;
      font-size: 16px;
      line-height: 1.6;
      margin-bottom: 24px;
    }
    .brand-name {
      color: ${primaryColor};
      font-weight: 600;
    }
    .btn {
      display: inline-block;
      background: ${primaryColor};
      color: white;
      text-decoration: none;
      padding: 14px 28px;
      border-radius: 8px;
      font-weight: 600;
      font-size: 16px;
      transition: opacity 0.2s;
    }
    .btn:hover {
      opacity: 0.9;
    }
    .info {
      margin-top: 16px;
      padding: 12px;
      background: #FEF3C7;
      border-radius: 8px;
      font-size: 14px;
      color: #92400E;
    }
  </style>
</head>
<body>
  <div class="card">
    <div class="logo">${logoHtml}</div>
    <div class="icon">
      <svg viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/></svg>
    </div>
    <h1>Paiement annulé</h1>
    <p>
      Votre paiement a été annulé.<br>
      Votre panier a été conservé.
    </p>
    <a href="${discordUrl}" class="btn">Retourner sur Discord</a>
    <div class="info">Vous pouvez reprendre votre commande à tout moment sur <span class="brand-name">${brandName}</span>.</div>
  </div>
</body>
</html>`;

return { html };

